//! Machine-extracted vectors from the official BIP texts (bitcoin/bips,
//! bip-0174.mediawiki "Test Vectors" Creator/Updater walkthrough and the
//! Base64 twin of every valid vector; bip-0371.mediawiki "Test Vectors"),
//! pulled out with a regex over the `Bytes in Hex` / `Base64 String` `<pre>`
//! blocks rather than hand-typed. Used by `update_test.zig` / `bip371_test.zig`.

pub const Pair = struct { hex: []const u8, b64: []const u8 };
pub const Case = struct { label: []const u8, hex: []const u8, b64: []const u8 };

